ed:UE,offlineHint:_E,downloadFailed:LE,removeOffline:GE,space:YE,checkAssets:KE,readyAssets:QE,fullscreen:XE,fullOption:ZE,fullHint:VE,fullFailed:JE,publicBeta:FE,floorDates:PE,downloadStarted:WE,restoreSound:IE,interruptionHint:eH,sampleFaces:tH,portraitCredits:nH,portraitPerson:aH,faceTimeTemplate:lH,originNote:iH,ruleChanged:sH,filter:cH,fontSize:oH,colour:rH,scroll:uH,enableDrawing:dH,select:fH,choosePosition:hH,finishBefore:mH,unit:pH,audioFailure:yH,audioHint:gH,selected:vH,times:bH,replayed:wH,savedCheckpoint:SH,storageError:xH,timingError:jH,loadError:TH,bestNone:$H,rules:NH,notes:AH,round:EH,timeTemplate:HH,secondsShort:RH,peopleQuantity:CH,contentVersion:MH,"rule-abstract":"五图行全对 +5；错漏 −1；全空 0。加总后最低零分。","rule-binary":"每行 30 位：全对 30，一错 15，两错或以上 0。最后有作答行按最右已填格计跨度；零须明确输入。","rule-numbers":"每行 40 位：全对 40，一错 20，两错或以上 0。末行按作答跨度，全对给全分，一错折半四舍五入。","rule-speedNumbers":"沿用 40 位数字行计分。城市一轮；国际／世界两轮取最高分。提前结束不额外加分。","rule-faces":"姓、名各正确 +1。姓／名分开统计；同一非空答案重复三次或以上，该组扣 0.5 × 次数。非负总分四舍五入；负分保留精确值并标记待核对。","rule-dates":"正确四位年份 +1；错误或部分年份 −0.5；全空 0。先加总，以零为下限，再四舍五入。事件及年份每轮不重复。","rule-cards":"每副 52 张：全对 52，一错 26，两错或以上 0。末副按作答跨度计分。同副不能重牌，清除不推移其他槽位。","rule-words":"每栏 20 词：全对 20，一错 10，两错或以上 0。末栏按作答跨度折半，总和后才取整。只接受所选语言的精确文字。","rule-audio":"完整 ABC 后每秒一位普通话数字，不显示数字。由首位连续计分，首错或空白即停止。提前结束会取消声音并标记缩短播放；音频故障另标中断。","rule-speedCards":"一副 52 张，两轮取佳。全对按实际记忆时间比较；未全对以连续正确张数比较，采计时间为 300 秒。",offlineUnsupported:DH,audioCue:kH,column:OH,exitFullscreen:zH,audioAwaitingRestore:qH,audioRowHint:BH,binaryDisplayTitle:UH,binaryDisplayHint:_H,binaryGroups:LH,binaryGroupsHint:GH,binaryHighlightRows:YH,binaryHighlightRowsHint:KH,binaryLines:QH,binaryLinesHint:XH,binaryColour:ZH,binaryShortcuts:VH,shortcutKeyboardRequired:JH,binaryShortcutGroups:FH,binaryShortcutRows:PH,binaryShortcutEnds:WH,binaryShortcutHint:IH,binaryPreviewKeyboardHint:eR,binaryTouchHint:tR,binaryPreview:nR,binarySample:aR,binaryPreviewHint:lR,binaryPreviewPhase:iR,binaryPreviewNavigation:sR,binaryPreviewRecallHint:cR,binaryPreviewMemoryHint:oR,